"""Build the reactor hub from the reviewed public dataset, without private inputs."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
E=lambda v:html.escape(' '.join(str(v if v is not None else 'Unknown').split()),quote=True)
def header():
    return '<header class="masthead"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">GN</span><span><strong>GlobalNuclearNews</strong><small>GLOBAL NUCLEAR INTELLIGENCE</small></span></a><nav aria-label="Main menu"><a href="news.html">Global Nuclear News</a><a href="theory.html">Nuclear Theory</a><a href="concepts.html">Concept Dictionary</a><a href="history.html">Nuclear History</a><a class="active" href="reactors.html">Reactor Data</a></nav></header>'
def frame(title,description,body,board=''):
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | GlobalNuclearNews</title><meta name="description" content="{E(description)}"><link rel="stylesheet" href="assets/styles.css?v=20261026-data"><link rel="stylesheet" href="assets/reactors.css?v=20261026"></head>
<body data-reactor-board="{board}">{header()}<main class="reactor-main">{body}</main><footer><span>© 2026 GlobalNuclearNews</span><a href="reactors.html">Reactor Data &amp; methodology</a></footer>{'<script src="assets/reactors.js?v=20261026" defer></script>' if board else ''}</body></html>\n'''
def record(r):
    status_label=r['status']+((' · '+r['businessState']) if r['businessState'] not in (None,'Active','Unknown') else '')
    badge=f'PRIS fields checked: {r["verifiedOn"]}' if r['verification']=='PRIS inventory fields' else (f'{r["verification"]} · checked {r["verifiedOn"]}' if r['verifiedOn'] else f'Baseline only · source review: {r["baselineReviewed"]} · not revalidated')
    facts=[('Country',r['country']),('Technology',r['model'] or r['type']),('Net capacity',str(r['netMWe'])+' MWe' if r['netMWe'] is not None else 'Unknown'),('Record unit',r['rowUnit'])]
    details=[('Facility scope',r['scope']),('Project state',r['businessState']),('Operator',r['operator']),('Gross capacity',str(r['grossMWe'])+' MWe' if r['grossMWe'] is not None else 'Unknown'),('Construction date',r['constructionDate']),('Commercial operation',r['commercialDate']),('Baseline review',r['baselineReviewed']),('Source observation date',r['sourceAsOf'] or 'See linked source'),('Site coordinates reviewed',r['coordinateAsOf'] if r['coordinates'] else 'Not mapped')]
    definition=lambda vals:'<dl>'+''.join(f'<div><dt>{E(k)}</dt><dd>{E(v)}</dd></div>' for k,v in vals)+'</dl>'
    return f'<article class="reactor-record"><div class="record-heading"><h3>{E(r["name"])}</h3><span class="status-tag">{E(status_label)}</span></div><p class="freshness {"baseline" if not r["verifiedOn"] else "checked"}">{E(badge)}</p>{definition(facts)}<details><summary>Details &amp; sources</summary><p>{E(r["statusNote"])}</p>{definition(details)}<ul>'+''.join(f'<li><a href="{E(s["url"])}" rel="noopener">{E(s["title"])}</a></li>' for s in r['sources'])+'</ul></details></article>'
def main():
    data=json.loads((ROOT/'assets/data/reactors.json').read_text(encoding='utf8'));rows=data['records']
    counts=data['prisCounts'];plans=sum(r['board']=='construction' for r in rows)
    cards=f'''<div class="data-cards"><a class="data-card" href="operating-reactors.html"><span class="eyebrow">THE OPERATING FLEET</span><h2>Operating Reactors <span aria-hidden="true">↗</span></h2><p>Explore {counts['Operational']} PRIS operational units by country, technology and capacity. Suspended units are available in a separate filter.</p><strong>Browse operating reactors →</strong></a><a class="data-card" href="construction-plans.html"><span class="eyebrow">THE PROJECT PIPELINE</span><h2>Construction &amp; Plans <span aria-hidden="true">↗</span></h2><p>Compare {counts['Under Construction']} PRIS construction units with a wider curated planning register. {plans} unit and project records in total.</p><strong>Browse construction &amp; plans →</strong></a></div>'''
    methodology='''<section class="data-method" id="methodology"><h2>How to read these data</h2><p><strong>Refresh: 26 October 2026.</strong> The current PRIS inventory was checked across its 38 country responses. The project register originates from a September 2026 review; many underlying IAEA 2025 tables describe 31 December 2024. Every record distinguishes a new check from inherited information.</p><ul><li><strong>Operational is an inventory status.</strong> It does not establish current electricity generation, availability or commercial acceptance. Suspended Operation is separate; 220 permanently shut-down and 3 decommissioned PRIS records are excluded from these views.</li><li><strong>Construction and planning are different.</strong> PRIS Under Construction is separate from developer-reported construction, licensing, siting and intent. A licence or announcement is not evidence of first nuclear concrete. Held, withdrawn and expired projects retain their business state.</li><li><strong>Coverage is curated.</strong> Power units, research/test facilities, demonstrations and project-level proposals are labelled separately. A project row may represent several units or an unresolved unit count. Record totals are not reactor totals. One inherited record without an attributable public source URL is retained locally and omitted from publication.</li><li><strong>Refresh scope is field-specific.</strong> PRIS status, capacity, model, operator and milestone dates were refreshed. Clinch River's construction permit, Kemmerer's developer-reported construction start and the licensing scope of Darlington's additional three units were checked against primary sources. Other baseline plans have not been revalidated. Original project names and some technical labels retain their source language.</li><li><strong>Map coverage is partial.</strong> Only unambiguous baseline site coordinates are plotted. Missing positions and approximate administrative centroids are omitted from the map, but their records remain searchable. Coordinates retain their original review date. Boundaries are geographic context only.</li><li><strong>Unknown is not zero.</strong> Missing and ambiguous capacities or dates remain unknown. MWe is electric capacity; net and gross figures are distinct. A first grid connection is not automatically commercial operation.</li></ul><p>Sources: <a href="https://pris-stats.iaea.org/">IAEA PRIS Analytics</a>, <a href="https://www.iaea.org/publications/reference-data-series-2">IAEA Reference Data Series No. 2</a>, and the public regulatory/operator sources attached to individual records. Basemap: <a href="https://www.naturalearthdata.com/">Natural Earth</a> v5.1.2, public domain, simplified.</p><p><a href="assets/data/reactors.json" download>Download the public dataset (JSON)</a> · <a href="assets/data/world-outline.json" download>Map geometry (JSON)</a></p></section>'''
    hub=f'<section class="data-hero"><p class="eyebrow">GLOBAL REACTOR DATA · 26 OCT 2026</p><h1>The fleet today.<br>The projects ahead.</h1><p class="data-lead">Explore operating nuclear reactors and the construction pipeline, with visible status, source dates and evidence.</p><div class="data-stats"><div><strong>{counts["Operational"]}</strong><span>PRIS operational units</span></div><div><strong>{counts["Under Construction"]}</strong><span>PRIS construction units</span></div><div><strong>{counts["Suspended Operation"]}</strong><span>Suspended operation · separate</span></div></div></section><section class="data-section">{cards}</section>'+methodology
    (ROOT/'reactors.html').write_text(frame('Reactor Data','Operating nuclear reactors and global construction plans, with country filters, capacities and source dates.',hub),encoding='utf8')
    for board,filename,title,desc in [('operating','operating-reactors.html','Operating Reactors','Search the PRIS operating fleet by country, reactor technology and capacity. Suspended operation is shown separately.'),('construction','construction-plans.html','Construction & Plans','Explore nuclear construction, licensing and planned projects. Distinguish verified PRIS construction from inherited planning records.')]:
        subset=[r for r in rows if r['board']==board and (board!='operating' or r['status']=='Operational')]
        warning='PRIS “Operational” is a fleet classification, not a statement that a unit is generating electricity now. Suspended units are excluded by default.' if board=='operating' else 'This register combines PRIS construction units with curated plans. Baseline-only records have not been revalidated; licensing and announced plans do not establish construction.'
        content=f'''<section class="data-hero compact"><p class="eyebrow"><a href="reactors.html">REACTOR DATA</a> / {board.upper()}</p><h1>{E(title)}</h1><p class="data-lead">{E(desc)}</p><p class="data-notice">{E(warning)}</p><nav class="data-tabs" aria-label="Reactor data views"><a {'aria-current="page"' if board=='operating' else ''} href="operating-reactors.html">Operating Reactors</a><a {'aria-current="page"' if board=='construction' else ''} href="construction-plans.html">Construction &amp; Plans</a></nav></section>
<section class="data-section"><form class="data-controls" id="data-controls" hidden><label>Search units or projects<input id="reactor-search" type="search" placeholder="Name, site, technology…"></label><label>Country<select id="reactor-country"><option value="">All countries</option></select></label><label>Status<select id="reactor-status"></select></label><label>Evidence<select id="reactor-evidence"><option value="">All evidence</option><option value="current">Checked in this refresh</option><option value="baseline">Baseline only</option></select></label><button type="reset">Reset filters</button></form>
<figure class="reactor-map" id="reactor-map" hidden><svg viewBox="0 0 1000 440" role="img" aria-labelledby="map-title map-description"><title id="map-title">Geographic distribution of selected reactor records</title><desc id="map-description">Only known baseline site locations are plotted. All records are available in the list below.</desc><g id="map-land"></g><g id="map-points"></g></svg><figcaption id="map-caption"></figcaption></figure>
<div class="results-heading"><h2>Explore the records</h2><p id="reactor-result-count" role="status">{len(subset)} records · showing the first 10</p></div><p class="data-downloads"><a href="assets/data/reactors.json" download>Download data (JSON)</a> · <a href="reactors.html#methodology">Sources &amp; methodology</a> · <a href="assets/data/world-outline.json" download>Map geometry</a></p>
<p id="data-error" class="data-notice" hidden></p><div id="reactor-list">{''.join(record(r) for r in subset[:10])}</div><nav id="reactor-pagination" class="pagination" aria-label="Record pages" hidden></nav><noscript><p>JavaScript is disabled. The first 10 records are shown above. Download the JSON dataset for the complete register and source links.</p></noscript></section>'''
        (ROOT/filename).write_text(frame(title,desc,content,board),encoding='utf8')
    return cards
if __name__=='__main__':main()
